gtQ(){return"\u0c88 \u0cb8\u0cc7\u0cb5\u0cc6 \u0ca8\u0ca8\u0c97\u0cc6 \u0c89\u0c9a\u0cbf\u0ca4\u0cb5\u0cc7?"},
gtR(){return"\u0c95\u0cca\u0c9f\u0cc7\u0cb6\u0ca8\u0ccd\u200c\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca4\u0cc6\u0cb0\u0cc6\u0ca6\u0cc1, \u0c90\u0c9f\u0c82\u0c97\u0cb3\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0c92\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0cca\u0ca4\u0ccd\u0ca4 \u0ca8\u0ccb\u0ca1\u0cbf, \u0c92\u0caa\u0ccd\u0caa\u0cbf \u0c92\u0ca4\u0ccd\u0ca4\u0cbf \u0cb8\u0cb9\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb9\u0cc6\u0cb8\u0cb0\u0cc1 \u0cac\u0cb0\u0cc6\u0caf\u0cbf\u0cb0\u0cbf."},
gtS(){return"\u0c95\u0cca\u0c9f\u0cc7\u0cb6\u0ca8\u0ccd \u0cb9\u0cc7\u0c97\u0cc6 \u0c92\u0caa\u0ccd\u0caa\u0cc1\u0cb5\u0cc1\u0ca6\u0cc1?"},
